    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    ceil_sqrt = math.ceil(math.sqrt(n))

    # Try to find a cycle of length >= ceil_sqrt using DFS
    color = [0] * (n + 1)  # 0 = unvisited, 1 = visiting, 2 = visited
    parent = [0] * (n + 1)
    path = []
    found_cycle = None

    def dfs_cycle(u, p):
        nonlocal found_cycle
        color[u] = 1
        path.append(u)

        for v in adj[u]:
            if v == p:
                continue

            if color[v] == 1:
                # Found back edge, cycle detected
                cycle_start = path.index(v)
                cycle = path[cycle_start:]
                if len(cycle) >= ceil_sqrt and found_cycle is None:
                    found_cycle = (2, len(cycle), list(cycle))
            elif color[v] == 0:
                parent[v] = u
                dfs_cycle(v, u)
                if found_cycle is not None:
                    return

        path.pop()
        color[u] = 2

    # Run DFS from node 1 (graph is connected, so this visits all)
    dfs_cycle(1, -1)

    if found_cycle is not None:
        return f"{found_cycle[0]}\n{found_cycle[1]}\n{found_cycle[2][1]}\n"

    # No long cycle found - construct independent set using BFS levels
    level = 0
    queue = [1]
    visited = {1}
    levels = {1: level}

    while queue:
        u = queue.pop(0)
        for v in adj[u]:
            if v not in visited:
                visited.add(v)
                levels[v] = level + 1
                queue.append(v)
        level += 1

    # Group vertices by level
    level_vertices = {}
    for v, l in levels.items():
        level_vertices.setdefault(l, []).append(v)

    # Greedily build independent set from deepest levels upward
    independent_set = []

    for lvl in sorted(level_vertices.keys(), reverse=True):
        for v in level_vertices[lvl]:
            if independent_set:
                for is_vertex in independent_set:
                    if is_vertex != v and v in adj[is_vertex]:
                        break
                else:
                    independent_set.append(v)
                    break

        if len(independent_set) >= ceil_sqrt:
            break

    # If not enough in independent_set, maybe use another heuristics
    if len(independent_set) < ceil_sqrt:
        # Try level-based independent set (vertices at same level in BFS)
        # This is an approximation but often works
        max_level_vertices = level_vertices[max(level_vertices.keys())]
