                can_add = True
                for existing in independent_set:
                    if v in adj[existing]:
                        can_add = False
                        break
                if can_add:
                    independent_set.append(v)

        if len(independent_set) < ceil_sqrt:
            # Fall back to any available independent set of sufficient size
            # Try picking vertices and filtering out neighbors
            candidates = list(adj[0])
            while len(independent_set) < ceil_sqrt and candidates:
                v = candidates[len(independent_set) % len(candidates)]
                if not any(u != v and v in adj[u] for u in independent_set):
                    independent_set.append(v)
                    candidates = [u for u in candidates if u != v]

    # Final verification - expand if needed
