import sys

def g(n, k):
    """Compute Grundy number for pile of size n with parameter k."""
    # Precompute enough values to find pattern
    memo = {}

    def compute(x):
        if x in memo:
            return memo[x]

        # Option 1: Remove 1 cow -> Grundy of x-1
        reachable = {compute(x - 1)}

        # Option 2: If x is even, split into k piles of x/2
        if x % 2 == 0:
            half = x // 2
            # XOR of k copies of g(half)
            if k % 2 == 1:
                # XOR of odd number of same values = that value
                reachable.add(compute(half))
            else:
                # XOR of even number of same values = 0
                reachable.add(0)

        # mex = minimum excluded value
        mex = 0
        while mex in reachable:
            mex += 1

        memo[x] = mex
        return mex

    return compute(n)

