def count_squares(grid, n, m):
    if n < 2 or m < 2:
        return 0

    count = 0

    # Count axis-aligned squares of size k×k (k >= 2)
    for k in range(2, min(n, m) + 1):
        for i in range(n - k + 1):
            for j in range(m - k + 1):
                if check_axis_square(grid, n, m, i, j, k):
                    count += 1

    # Count diamond squares (radius r >= 1)
    for cx in range(n):
        for cy in range(m):
            for r in range(1, min(n, m) + 1):
                if check_diamond_square(grid, n, m, cx, cy, r):
                    count += 1

    return count


def check_axis_square(grid, n, m, r1, c1, k):
    """Check if there's a valid k×k axis-aligned square with top-left at (r1, c1)"""
    r2, c2 = r1 + k - 1, c1 + k - 1

    # Border must be all 1s
    for c in range(c1, c2 + 1):
        if grid[r1][c] != '1' or grid[r2][c] != '1':
            return False

    for r in range(r1, r2 + 1):
        if grid[r][c1] != '1' or grid[r][c2] != '1':
            return False

    # No foreign 1s touching the square (check all adjacent cells)
    for r_adj in range(r1 - 1, r2 + 2):
        for c_adj in range(c1 - 1, c2 + 2):
            if r_adj != r1 and r_adj != r2 and c_adj != c1 and c_adj != c2:
                if 0 <= r_adj < n and 0 <= c_adj < m:
                    if grid[r_adj][c_adj] == '1':
                        return False

    return True


def check_diamond_square(grid, n, m, cx, cy, r):
    """Check if there's a valid diamond square with center (cx, cy) and radius r"""

    # Bottom check - ensure it fits
    if cx - r < 0 or cx + r >= n or cy - r < 0 or cy + r >= m:
        return False

    # All border cells (Manhattan distance exactly r) must be 1
    for dr in range(-r, r + 1):
        for dc in range(-r, r + 1):
            if abs(dr) + abs(dc) == r:
                if grid[cx + dr][cy + dc] != '1':
                    return False

    # No foreign 1s touching the diamond (check adjacent cells)
    # Check cells at Manhattan distance r+1 (adjacent to border)
    for dr in range(-r - 1, r + 2):
        for dc in range(-r - 1, r + 2):
            if abs(dr) + abs(dc) == r + 1:
                if grid[cx + dr][cy + dc] != '0':
                    return False

    return True

