def dfs_long_path(start, adj, min_len):
    visited = {start}
    stack = [(start, [start])]

    while stack:
        node, path = stack.pop()

        if len(path) >= min_len:
            return path

        for neighbor in sorted(adj[node], reverse=True):
            if neighbor not in visited:
                visited.add(neighbor)
                stack.append((neighbor, path + [neighbor]))
    return []

def find_cycle(rep, adj):
    """Find a cycle that includes rep as representative"""
    visited = {rep}
    parent = {rep: None}
    stack = [rep]
    path = [rep]

    while stack:
        node = stack.pop()
        for neighbor in adj[node]:
            if neighbor == rep:
                if len(path) >= 3:
                    return path.copy()
            elif neighbor not in visited:
                visited.add(neighbor)
                parent[neighbor] = node
                stack.append(neighbor)
                path.append(neighbor)

    # Try to find back edge cycle
    visited = {rep}
    parent = {rep: None}
    queue = [rep]

    while queue:
        node = queue.pop(0)
        for neighbor in adj[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                parent[neighbor] = node
                queue.append(neighbor)
            elif neighbor in visited and neighbor != parent[node] and neighbor != rep:
                # Found cycle
                cycle = []
                curr = node
                while curr != neighbor:
                    cycle.append(curr)
                    curr = parent[curr]
                cycle.append(neighbor)
                return cycle

    return []

