def is_geometric(arr):
    """Check if arr is a geometric progression."""
    n = len(arr)
    if n <= 2:
        return True

    if all(x == 0 for x in arr):
        return True

    # Find first non-zero element
    first_nonzero = -1
    for i, x in enumerate(arr):
        if x != 0:
            first_nonzero = i
            break

    if first_nonzero == -1:
        return True

    # All elements before first non-zero must be zero (already checked)

    # If first non-zero has a zero successor, all remaining must be zero
    start = first_nonzero
    if start + 1 < n and arr[start + 1] == 0:
        return True

    # Use cross-multiplication to avoid floating point issues
    # For GP with ratio r: a[second]/a[first] = a[i]/a[i-1]
    # Cross-multiplied: a[i] * a[first] = a[i-1] * a[second]

    for i in range(start + 2, n):
        # arr[i] must satisfy: arr[i] / arr[i-1] = arr[start+1] / arr[start]
        # Which means: arr[i] * arr[start] == arr[i-1] * arr[start+1]
        # But handle special case where one side might be zero

        if arr[i] == 0 or arr[i-1] == 0 or arr[start] == 0 or arr[start+1] == 0:
            # If any involved is zero, use direct ratio check with tolerance
            continue

        if arr[i] * arr[start] != arr[i-1] * arr[start+1]:
            return False

    return True

