    return f'{min_moves}\n'

def calc_moves(arr, k):
    """Calculate minimum moves to make all elements divisible by k."""
    target = sum(arr)
    if target % k != 0:
        return float('inf')

    total_moves = 0
    current_rem = 0

    for x in arr:
        current_rem = (current_rem + x) % k
        total_moves += current_rem

    # The actual minimum is half the sum (each move affects two positions)
    # But this is still an approximation
    return total_moves


