def solution(input_str):
    """
    Solves the stable roommates problem for city rail pairing.

    Args:
        input_str: String containing problem input

    Returns:
        String with matching results or -1 if no stable matching exists
    """
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    # Parse cost matrix
    full_costs = [[0] * n for _ in range(n)]
    for i in range(n):
        row_data = list(map(int, lines[i + 1].split()))
        idx = 0
        for j in range(n):
            if j != i:
                full_costs[i][j] = row_data[idx]
                idx += 1

    # Build preferences: lower cost = higher preference
    prefs = []
    for i in range(n):
        others = [(j, full_costs[i][j]) for j in range(n) if j != i]
        others.sort(key=lambda x: x[1])  # Sort by cost ascending
        prefs.append([j for j, _ in others])

    # Gale-Shapley algorithm for stable roommates
    matching = [-1] * n  # matching[i] = partner of i
    free_nodes = list(range(n))  # unmatched nodes
    proposals = [0] * n  # next preference to propose for each free node
    ptr = [0] * n

    while free_nodes:
        u = free_nodes.pop(0)

        if ptr[u] >= len(prefs[u]):
            continue

        v = prefs[u][ptr[u]]
        ptr[u] += 1

        if matching[v] == -1:
            # v is free, match them
            matching[v] = u
            matching[u] = v
        else:
            # v is matched with w
            w = matching[v]
            if full_costs[v][u] < full_costs[v][w]:
                # v prefers u over w
                matching[v] = u
                matching[u] = v
                matching[w] = -1
                free_nodes.append(w)
            else:
                # v prefers current partner, u not matched
                free_nodes.append(u)

    # Verify all nodes are matched
    if any(m == -1 for m in matching):
        return "-1\n"

    # Check if matching is stable - no blocking pairs
    stable = True
    for u in range(n):
        v = matching[u]
        for w in range(n):
            if w == v or w == u:
                continue
            # Check if u prefers w over v
            if full_costs[u][w] < full_costs[u][v]:
                # Check if w prefers u over their current partner
                if full_costs [w][u] < full_costs[w][matching[w]]:
                    stable = False
                    break
        if not stable:
            break

    if not stable:
        return "-1\n"

    # Output result
    result = []
    for i in range(n):
        result.append(str(matching[i]))
    return "\n".join(result) + "\n"


