                    escaped_in_this_ray = False
                    for step in range(1000):
                        tx = sx + theta * math.cos(theta) * step * 0.5
                        ty = sy + theta * math.sin(theta) * step * 0.5

                        # Check if we're still in bounds
                        if not (min_x - 10 < tx < max_x + 10 and min_y - 10 < ty < max_y + 10):
                            escaped_in_this_ray = True
                            break

                        # Check if point is in any circle
                        in_circle = False
                        for (cx, cy) in circles:
                            if math.hypot(tx - cx, ty - cy) <= r + 1e-9:
                                in_circle = True
                                break
                        if in_circle:
                            break

                    if escaped_in_this_ray:
                        ray_escaped = True
                        break

            if ray_escaped:
                escaped = True

            if not escaped:
                return True  # Found a trapped white point

        return False  # All white points can escape

    # Binary search for the smallest time when no holes exist
    lo, hi = 0.0, 100000.0

    # Check if holes exist at very large time
    if not check_hole_exists_at_radius(hi):
        return "-1\n"
    if not check_hole_exists_at_radius(0.0):
        return "-1\n"

    ans = hi

    for _ in range(100):
        mid = (lo + hi) / 2
        if check_hole_exists_at_radius(mid):
            # Holes still exist, need larger time
            lo = mid
        else:
            # No holes, record this time
            ans = mid
            hi = mid

    return f"{ans:.6f}\n"

def solution(input_str):
    """
    Process queries for dynamic set of pairs with max(x*q + y) calculations.

    Queries:
    - Type 1: Add pair (a, b)
    - Type 2: Remove pair from query index i
    - Type 3: Find max(x*q + y) over all pairs
    """
