        if t == 1:
            queries.append((1, parts[1], parts[2], len(queries) + 1))
        elif t == 2:
            queries.append((2, parts[1], 0, len(queries) + 1))
        elif t == 3:
            queries.append((3, parts[1], 0, len(queries) + 1))

    if not queries:
        return ""

    # Track active pairs and their creation times
    active_pairs = set()
    creation_to_pair = {}  # creation_idx -> (a, b)
    pair_to_creation = {}  # (a, b) -> creation_idx

    results = []

    for _, (t, a, b, creation_idx) in enumerate(queries, 1):
        if t == 1:
            # Add pair (a, b) at query creation_idx
            active_pairs.add((a, b))
            pair_to_creation[(a, b)] = creation_idx
            creation_to_pair[creation_idx] = (a, b)

        elif t == 2:
            # Remove pair from query index i (a = i)
            query_to_remove = a
            if query_to_remove in creation_to_pair:
                pair_to_remove = creation_to_pair[query_to_remove]
                active_pairs.discard(pair_to_remove)
                if pair_to_remove in pair_to_creation:
                    del pair_to_creation[pair_to_remove]

        elif t == 3:
            # Find max(x*q + y)
            q = a
            if not active_pairs:
                results.append("EMPTY SET")
            else:
                max_val = -float('inf')
                for x, y in active_pairs:
                    val = x * q + y
                    if val > max_val:
                        max_val = val
                results.append(str(max_val))

    return '\n'.join(results)

