def solution(input_string):
    from functools import lru_cache

    MOD = 1000000007
    n, m = map(int, input_string.split())

    if n == 1 and m == 1:
        return '0\n'

    # Precompute factorials for nCr
    fact = [1] * (n + m + 2)
    inv = [1] * (n + m + 2)
    inv[m] = pow(m, MOD - 2, MOD)

    for i in range(1, n + m + 2):
        fact[i] = fact[i-1] * i % MOD

    def nCr_mod(n, r):
        if r < 0 or r > n:
            return 0
        num = fact[n] % MOD
        den = fact[r] * fact[n - r] % MOD
        return num * pow(den, MOD - 2, MOD) % MOD

    # DP approach
    @lru_cache(maxsize=None)
    def dp_left(h, L, R):
        """Count ways to go up from pivot with height h, ending with columns L, R"""
        if h == 0:
            return 1
        if L >= R:
            return 0

        total = 0
        for new_L in range(1, L + 1):
            for new_R in range(R, m + 1):
                if new_L < new_R:
                    total = (total + dp_left(h - 1, new_L, new_R)) % MOD
        return total

    @lru_cache(maxsize=None)
    def dp_right(h, L, R):
        """Count ways to go down from pivot with height h"""
        if h == 0:
            return 1
        if L >= R:
            return 0

        total = 0
        for new_L in range(L, m - 1):
            for new_R in range(new_L + 1, R + 1):
                total = (total + dp_right(h - 1, new_L, new_R)) % MOD
        return total

    result = 0
    for t in range(1, n + 1):
        for L in range(1, m):
            for R in range(L + 1, m + 1):
                a = t - 1
                b = n - t

                if a == 0:
                    ways_up = 1 * (R - L)
                else:
                    ways_up = dp_left(a, L, R)

                if b == 0:
                    ways_down = 1 * (R - L)  
                else:
                    ways_down = dp_right(b, L, R)

                result = (result + (ways_up * ways_down) % MOD) % MOD

    return f"{result}\n"

