def solution(input_str):
    import sys

    def get_prime_factors(num, cache):
        """Get prime factors of a number efficiently"""
        if num in cache:
            return cache[num]

        factors = set()
        d = 2
        temp = num
        while d * d <= temp:
            if temp % d == 0:
                factors.add(d)
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            factors.add(temp)

        cache[num] = factors
        return factors

    lines = input_str.strip().split('\n')
    n, a, b = map(int, lines[0].strip().split())
    arr = list(map(int, lines[1].strip().split()))

    if n == 1:
        return '0\n'

    cache = {2: {2}}
    candidates = {2}

    # Collect prime factors from first few elements to avoid TLE
    indices_to_check = [0]
    for i in range(1, min(3, n)):
        indices_to_check.append(i)
    indices_to_check.append(n-1)

    for idx in indices_to_check:
        for f in get_prime_factors(arr[idx], cache):
            candidates.add(f)

    def calculate_cost(arr, g):
        if g == 2:
            # For g=2, only even numbers are "good"
            must_remove_start = -1
            must_remove_end = -1
            changes_outside = 0

            odd_indices = []
            for i in range(n):
                if arr[i] % 2 != 0:
                    odd_indices.append(i)

            if not odd_indices:
                return 0

            changes = len(odd_indices) * b

            if len(odd_indices) == 1:
                return changes

            start = odd_indices[0]
            end = odd_indices[-1]
            removal_cost = (end - start + 1) * a
            changes_inside = (end - start + 1)
            changes_outside = changes - changes_inside

            return min(changes, removal_cost + changes_outside * b)

        # For g > 2
        changes = 0
        must_remove_start = -1

        # Mark elements that need removal (not divisible and remainder != 1, g-1)
        for i in range(n):
            r = arr[i] % g
            if r != 0 and r != 1 and r != g - 1:
                must_remove_start = i
                break

        if must_remove_start == -1:
            # No removal needed
            for i in range(n):
                r = arr[i] % g
                if r != 0 and (r != 1 and r != g - 1):
                    continue  # already handled by removal logic if exists
                if r == 1 or r == g - 1:
                    changes += 1

            return changes * b

        # Find end of removal segment
        for i in range(n):
            r = arr[i] % g
            if r != 0 and r != 1 and r != g - 1:
                must_remove_end = i
                break

        removal_cost = (must_remove_end - must_remove_start + 1) * a
        changes_outside = 0

        for i in range(n):
            if must_remove_start <= i <= must_remove_end:
                continue
            r = arr[i] % g
            if r == 1 or r == g - 1:
                changes_outside += 1

        return min(changes * b, removal_cost + changes_outside * b)

    ans = float('inf')

    for g in candidates:
        cost = calculate_cost(arr, g)
        ans = min(ans, cost)

    return str(ans) + '\n'
