    lines = input_str.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    p_set = set(p)
    val_to_index = {v: i for i, v in enumerate(p)}

    # Build graph where edges represent "must be in same set" constraints
    graph = [[] for _ in range(n)]

    for i in range(n):
        val = p[i]
        comp_a = a - val
        comp_b = b - val

        # If a-complement exists, they must be in the same set
        if comp_a in p_set:
            j = val_to_index[comp_a]
            if i != j:
                graph[i].append(j)
                graph[j].append(i)

        # If b-complement exists (and distinct), they must be in the same set
        if comp_b in p_set:
            j = val_to_index[comp_b]
            if i != j:
                graph[i].append(j)
                graph[j].append(i)

    # 2-color the graph to assign sets
    color = [-1] * n  # -1: uncolored, 0: set A, 1: set B

    for i in range(n):
        if color[i] == -1:
            stack = [(i, 0)]
            color[i] = 0
            while stack:
                node, c = stack.pop()
                for neighbor in graph[node]:
                    if color[neighbor] == -1:
                        color[neighbor] = 1 - c
                        stack.append((neighbor, 1 - c))
                    elif color[neighbor] == color[node]:
                        # Not bipartite - conflict
                        return "NO"

    # Verify constraints are satisfied
    for i in range(n):
        val = p[i]
        comp_a = a - val
        comp_b = b - val

        if color[i] == 0:  # In set A
            # If a-complement exists, it must also be in A
            if comp_a in p_set:
                if color[val_to_index[comp_a]] != 0:
                    return "NO"
        else:  # In set B
            # If b-complement exists, it must also be in B
            if comp_b in p_set:
                if color[val_to_index[comp_b]] != 1:
                    return "NO"

    result = []
    for i in range(n):
        result.append("1" if color[i] == 0 else "0")

    return "".join(result) + "\n"

