        new_dp = {}
        for h, count in dp.items():
            # Add this box to the stack
            new_h = h + height
            # The bottom edge of this box is at height h (before adding this box)
            base_height = h

            # If this is an important box and its bottom is in [l, r], count it
            if is_important and l <= base_height <= r:
                new_count = count + 1
            else:
                new_count = count

            new_dp[new_h] = max(new_dp.get(new_h, -1, -2), new_count)

        dp = new_dp

    # Find the maximum across all reachable final states
    ans = max(dp.values()) if dp else 0
    return str(ans)

