def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    idx = 0
    n, m = map(int, lines[idx].split())
    idx += 1

    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        a, b, l = map(int, lines[idx].split())
        idx += 1
        adj[a].append((b, l))

    idx += 1
    q = int(lines[idx])
    idx += 1

    queries = []
    for _ in range(q):
        v, s, t = map(int, lines[idx].split())
        idx += 1
        queries.append((v, s, t))

    # Tarjan's algorithm for SCCs
    disc = [-1] * (n + 1)
    low = [0] * (n + 1)
    on_stack = [False] * (n + 1)
    stack = []
    disc_count = 0
    scc_id = [-1] * (n + 1)
    scc_num = 0

    def tarjan(u):
        nonlocal disc_count, scc_num
        disc[u] = low[u] = disc_count
        disc_count += 1
        stack.append(u)
        on_stack[u] = True

        for v, _ in adj[u]:
            if disc[v] == -1:
                tarjan(v)
                low[u] = min(low[u], low[v])
            elif on_stack[v]:
                low[u] = min(low[u], disc[v])

        if low[u] == disc[u]:
            while stack:
                node = stack.pop()
                on_stack[node] = False
                scc_id[node] = scc_num
                if node == u:
                    break
            scc_num += 1

    for i in range(1, n + 1):
        if disc[i] == -1:
            tarjan(i)

    # Get nodes for each SCC
    scc_nodes = [[] for _ in range(scc_num)]
    for i in range(1, n + 1):
        scc_nodes[scc_id[i]].append(i)

    # Find GCD of all cycles in each SCC
    scc_gcd = [0] * scc_num

    for scidx in range(scc_num):
        if not scc_nodes[scidx]:
            continue

        # Build subgraph for this SCC
        in_scc = set(scc_nodes[scidx])

        def dfs_cycle(start):
            """Find cycles using DFS and compute GCD of all cycle lengths"""
            nonlocal scc_gcd
            scc_gcd[scidx] = 0
            visited = set()
            dist = {}
            path_gcd = 0

            def backtrack(node, d):
                nonlocal path_gcd
                if node in dist:
                    # Found a cycle or continue on path
                    pass

                for v, w in adj[node]:
                    if v not in in_scc:
                        continue

                    if v == start and node != start:
                        # Found back edge to start
                        cycle_len = d - dist.get(start, d) + w
                        path_gcd = gcd(path_gcd, cycle_len)
                    elif v not in dist:
                        dist[v] = d + w
                        backtrack(v, d + w)
                        if v in dist:
                            dist.pop(v)
                    else:
                        # v already visited - might have a cycle
                        past_d = dist[v]
                        cycle_len_to_close = d - past_d + w
                        path_gcd = gcd(path_gcd, cycle_len_to_close)

            dist[start] = 0
            backtrack(start, 0)
            scc_gcd[scidx] = path_gcd

        dfs_cycle(scc_nodes[scidx][0])

    # Process queries
    results = []
    for v, s, t in queries:
        if scc_id[v] == -1:
            results.append("NO")
        else:
            g = scc_gcd[scc_id[v]]
            if g == 0:
                results.append("NO")
            else:
                if s % g == 0:
                    results.append("YES")
                else:
                    results.append("NO")

    return '\n'.join(results)


