def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    m = int(lines[0])
    output = []

    precomputed_sets = {}

    def generate_valid_sets():
        """Generate all valid set (a_pts, b_pts) pairs"""
        pairs = []
        for winner_pts in range(25, 101):
            for loser_pts in range(max(0, winner_pts - 2), winner_pts + 1):
                if loser_pts < 25:
                    pairs.append((winner_pts, loser_pts))
                elif winner_pts - loser_pts >= 2:
                    pairs.append((winner_pts, loser_pts))
        return pairs

    valid_pools = generate_valid_sets()

    def check_and_build(a, b, a_wins, b_wins):
        """Try to build valid sets for this match outcome"""
        if a_wins == 3 and b_wins == 0:
            return build_sets_recursive(a, b, 0, 0, [], a_wins, b_wins)
        elif a_wins == 3 and b_wins == 1:
            return build_sets_recursive(a, b, 0, 0, [], a_wins, b_wins, b_embarred=False)
        return None

    def build_sets_recursive(remaining_a, remaining_b, win_counter, set_idx, current_sets, target_a, target_b, final_b_set=False):
        if set_idx > 5:
            return None

        if win_counter == target_a + target_b:
            if remaining_a == 0 and remaining_b == 0:
                return current_sets

            for s_a, s_b in valid_pools:
                new_sets = current_sets + [(s_a, s_b)]
                new_rem_a = remaining_a - s_a
                new_rem_b = remaining_b - s_b

                if new_rem_a < 0 or new_rem_b < 0:
                    continue

                result = build_sets_recursive(new_rem_a, new_rem_b, win_counter, set_idx + 1, new_sets, target_a, target_b, False)
                if result:
                    return result

            return None

        # Try adding A winning set
        for score in valid_pools:
            s_a, s_b = score
            if s_a < remaining_a and s_b < remaining_b:
                result = build_sets_recursive(remaining_a - s_a, remaining_b - s_b, win_counter + 1, set_idx + 1, current_sets + [(s_a, s_b)], target_a, target_b, False)
                if result:
                    return result

        # Try adding B winning set
        for score in valid_pools:
            s_a, s_b = score
            if s_a < remaining_a and s_b < remaining_b:
                result = build_sets_recursive(remaining_a - s_a, remaining_b - s_b, win_counter, set_idx + 1, current_sets + [(s_a, s_b)], target_a, target_b, False)
                if result:
                    return result

        return None

    def find_valid_sets_recursive(remaining_a, remaining_b, set_count, sets):
        if set_count == 0:
            return (remaining_a == 0 and remaining_b == 0), sets

        if remaining_a < 0 or remaining_b < 0:
            return False, None

        for s_a, s_b in valid_pools:
            if s_a <= remaining_a and s_b <= remaining_b:
                if find_valid_sets_recursive(remaining_a - s_a, remaining_b - s_b, set_count - 1, sets + [(s_a, s_b)][0:0]):
                    remain, result = find_valid_sets_recursive(remaining_a - s_a, remaining_b - s_b, set_count - 1, sets + [(s_a, s_b)])
                    if remain:
                        return True, [(s_a, s_b)] + result

        return False, None

    def try_build(a, b, a_wins, b_wins):
        if a_wins + b_wins > 5 or (a_wins + b_wins > 3 and a_wins != 3):
            return None

        for first_set in valid_pools:
            for second_set in valid_pools:
                for third_set in valid_pools:
                    for fourth_set in valid_pools:
                        for fifth_set in valid_pools:
                            combo = [first_set, second_set, third_set, fourth_set, fifth_set][0:a_wins + b_wins]
                            if build_valid_combo(a, b, combo):
                                return combo
        return None

    def build_valid_combo(a, b, combo):
        scored_a = sum(s[0] for s in combo)
        scored_b = sum(s[1] for s in combo)
        return scored_a == a and scored_b == b

    def find_sets(a, b, a_wins, b_wins):
        """Try to find valid sets for given outcome"""
        total_sets = a_wins + b_wins

        if total_sets == 0:
            return [] if a == 0 and b == 0 else None

        if total_sets == 1:
            for s in valid_pools:
                if s[0] + s[1] == a + b:
                    return [s]
            return None

        if total_sets == 2:
            for s1 in valid_pools:
                for s2 in valid_pools:
                    if s1[0] + s2[0] == a and s1[1] + s2[1] == b:
                        return [s1, s2]
            return None

        if total_sets == 3:
            for s1 in valid_pools:
                for s2 in valid_pools:
                    for s3 in valid_pools:
                        if s1[0] + s2[0] + s3[0] == a and s1[1] + s2[1] + s3[1] == b:
                            return [s1, s2, s3]
            return None

        if total_sets == 4:
            for s1 in valid_pools:
                for s2 in valid_pools:
                    for s3 in valid_pools:
                        for s4 in valid_pools:
                            if (s1[0] + s2[0] + s3[0] + s4[0] == a and 
                                s1[1] + s2[1] + s3[1] + s4[1] == b):
                                return [s1, s2, s3, s4]
            return None

        if total_sets == 5:
            for s1 in valid_pools:
                for s2 in valid_pools:
                    for s3 in valid_pools:
                        for s4 in valid_pools:
                            for s5 in valid_pools:
                                if (s1[0] + s2[0] + s3[0] + s4[0] + s5[0] == a and
                                    s1[1] + s2[1] + s3[1] + s4[1] + s5[1] == b):
                                    return [s1, s2, s3, s4, s5]
            return None

        return None

    for i in range(1, m + 1):
        parts = lines[i].split()
        if len(parts) != 2:
            output.append("Impossible\n")
            continue

        a, b = int(parts[0]), int(parts[1])

        best_outcome = None
        best_sets = None

        # Try outcomes from best to worst for Team A
        order = [(3, 0), (3, 1), (3, 2), (2, 3), (1, 3), (0, 3)]

        for A_wins, B_wins in order:
            total_sets = A_wins + B_wins
            if total_sets > 5:
                continue

            sets = find_sets(a, b, A_wins, B_wins)
            if sets:
                best_outcome = (A_wins, B_wins)
                best_sets = sets
                break

        if not best_outcome:
            output.append("Impossible\n")
        else:
            output.append(f"{best_outcome[0]}:{best_outcome[1]}\n")
            sets_str = " ".join(f"{s[0]}:{s[1]} " for s in best_sets)
            output.append(sets_str + "\n")

    return "".join(output)
